var n=`0364-kasknopfle`;var t=`world-0364`;var s=`LI`;var r=`western-europe`;var l=4;var a=28;var o={en:`Käsknöpfle`,ua:`Кескньопфле`};var g={en:`A traditional Liechtenstein dish made with all-purpose flour, chicken egg, gruyère, yellow onion. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Ліхтенштейн. Основні інгредієнти: пшеничне борошно універсальне, куряче яйце, грюєр, жовта цибуля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`all-purpose-flour`,350,`g`],[`chicken-egg`,4,`pcs`],[`water`,160,`ml`],[`table-salt`,4,`g`]]},{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[[`water`,1600,`ml`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:8,i:[[`gruyere`,270,`g`],[`unsalted-butter`,60,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`yellow-onion`,190,`g`]]}];var u={slug:n,id:t,country:`LI`,region:r,servings:4,minutes:28,title:o,text:g,steps:d};export{s as country,u as default,t as id,a as minutes,r as region,l as servings,n as slug,d as steps,g as text,o as title};